  R.lesson["w7d6-lesson"] = {
    title: "Эндшпиль: Архитектор",
    md: String.raw`Две недели назад дизайн-раунд был чистым листом. Теперь у тебя есть метод, дюжина разобранных кейсов и арифметика, чтобы подкрепить свои утверждения. Этот последний урок превращает всё это в поведение на собеседовании: чек-лист, который ты прогоняешь под давлением, ловушки, топящие сильных кандидатов, и что со всем этим делать в первые 90 дней на работе.

### Семь шагов, по порядку

Дизайн-раунд длится 45-60 минут. Трать их вот так — и проговаривай названия шагов вслух, потому что интервьюеры оценивают структуру не меньше содержания.

1. **Уточни задачу (3-5 мин).** Кто пользователь, какую работу он нанимает эту фичу делать и что значит «готово»? Расплывчатые просьбы («добавьте AI в наш продукт») — это и есть тест: кандидат, который сразу начинает рисовать квадратики, уже потерял баллы.
2. **Требования, с числами (5 мин).** Сначала функциональный список, потом нефункциональные: масштаб (DAU, QPS, размер корпуса), цель по задержке (p95, а если стримит — то и TTFT), свежесть, бюджет на запрос, комплаенс и резидентность данных. Выпиши числа на доску; каждое дальнейшее решение будет на них ссылаться.
3. **Метрики успеха и план оценки (5 мин).** До архитектуры. Какая онлайн-метрика, какие ограждения могут заблокировать запуск и как выглядит офлайновый eval-сет: сколько примеров, кем размечены, как часто обновляются? Это самая недоотвеченная часть AI-дизайн-раундов и место, где ты можешь заметно превзойти остальных.
4. **Данные и стратегия по модели (5-8 мин).** Какие данные есть, что придётся создавать, купить или построить — и инстинкт *сначала бейзлайн*: запромптить API-модель, измерить, а потом обосновывать всё, что тяжелее.
5. **Архитектура (10-15 мин).** Нарисуй загрузку данных, хранилище/индекс и путь обслуживания, а потом проведи один запрос от начала до конца с бюджетом задержки на каждый шаг. Квадратики без прохода запроса — это декорация.
6. **Масштаб, стоимость, надёжность (8-10 мин).** Арифметика ёмкости, уровни кэша, цепочка фолбэков, лестница деградации, SLO. Одно число бьёт пять прилагательных.
7. **Раскатка и риски (5 мин).** Канарейка с гейтами, мониторинг, что сломается через полгода (дрейф, петли обратной связи, депрекейты у провайдера) и что ты сознательно вырезал из v1.

### Пять ловушек

- **Архитектура раньше метрик.** Если ты не можешь сказать, как поймёшь, что фича работает, у дизайна нет ограничений.
- **Суп из баззвордов.** «Мы возьмём RAG с агентным мультимодальным пайплайном» не говорит ничего. Числа, компромиссы и названная альтернатива, которую ты отверг, говорят всё.
- **Оверинжиниринг в v1.** Мультиагентность, файнтюнинг и селф-хостинг вполне защитимы — *после* того как ты показал, что простое не справляется. Предлагать их первыми читается как неопытность.
- **Игнорирование отказов и стоимости.** Каждый сеньорный интервьюер спросит «что будет, когда провайдер ляжет» и «сколько это стоит на запрос». Держи оба ответа наготове до вопроса.
- **Отсутствие мнения.** Перечислить три варианта и дать интервьюеру выбрать — джуновский ход. Выбирай, обосновывай тем ограничением, которое всё решило, и называй, что заставило бы тебя передумать.

### Проводи собственные мок-собеседования

Кейсы Додзё стоят ровно столько, сколько ты в них вложил. Протокол: таймер на 45 минут, телефон убран, **говори вслух** (молчаливое размышление не качает нужную мышцу) и печатай свой ответ *до* того, как раскроешь эталонный. Отмечай пункты рубрики честно — число покрытия и есть весь смысл, а завышая его, ты обворовываешь только себя. Целься в 70%+ покрытия; кейс, который ты завалил, перепройди через две недели с холодной головы. Десять кейсов, сделанных так, бьют пятьдесят пролистанных.

Два дополнения, которые окупаются: запиши себя один раз и переслушай (услышишь и слова-паразиты, и увиливания), и отрабатывай первые пять минут снова и снова — уточняющие вопросы это самая рычаговая и самая репетируемая часть раунда.

### Преврати эти кейсы в тезисы для портфолио

Теперь у тебя есть дюжина дизайнов, о которых можно говорить. Переведи каждый в девяностосекундную историю одной и той же формы: **ограничение, решение, компромисс, число.** Например: «Для агента поддержки, умеющего возвращать деньги, ограничением было то, что возвраты необратимы и аудируются, поэтому я вынес авторизацию в детерминированный оценщик политик вне модели и автоматически одобрял только суммы до $20 для верифицированных клиентов — так поверхность инъекционной атаки упирается в „предложение отклонено“, а люди выпадают из 80% цикла.»

Запомни по три числа на кейс (масштаб, бюджет задержки, стоимость запроса). Интервьюеры запоминают кандидатов, которые цитируют собственную арифметику. А если ты что-то из этого делал по-настоящему — пусть игрушечную версию на 200 документов, но с настоящим eval-сетом, — начинай с этого: работающий eval-харнесс впечатляет сильнее большого файнтюна.

### 30-60-90 на первой работе AI-инженером

- **Дни 1-30: заслужи доверие маленькими, но законченными делами.** Выкати одно сквозное изменение, каким бы мелким оно ни было. Прочитай eval-харнесс и ранбук дежурного раньше кода модели — там живёт настоящее знание команды. Записывай вопросы, на которые никто не смог ответить; этот список — твой первый роадмап.
- **Дни 31-60: возьми поверхность под себя.** Возьми фичу с привязанной метрикой, встань в ротацию дежурств и обвесь метриками то, что раньше было невидимым (стоимость запроса, доля фолбэков, оценка судьи по сегментам). Стать человеком, который сделал проблему измеримой, — самый быстрый путь к авторитету.
- **Дни 61-90: предложи одно архитектурное изменение с числами.** Стоимость, качество и риск, с планом канарейки. Это тот момент, когда ты перестаёшь быть новичком и становишься инженером, к которому другие приносят свои дизайны.

### ⚠️ Типичные ловушки

- Отвечать на вопрос, который ты хотел бы услышать, вместо заданного.
- Сжечь 20 минут на требованиях и так и не дойти до архитектуры — следи за часами и говори «потрачу здесь пять минут».
- Отказываться выбирать («зависит от»), так и не сказав, от чего именно зависит.
- Подавать кейс из портфолио как туториал, а не как решение, которое ты принял и защитил.
- Считать первые 90 дней поводом всё переписать.

### 🎤 На собеседованиях спрашивают

- «Вот расплывчатая просьба от руководства. Преврати её в дизайн.» (Это и есть весь раунд.)
- «Что бы ты вырезал, чтобы запуститься за шесть недель?»
- «Как ты через три месяца поймёшь, что эта фича проваливается?»
- «Расскажи о дизайн-решении, о котором потом пожалел.»
- «Что ты сделаешь первым в свой первый месяц здесь?»

### TL;DR

- Прогоняй семь шагов по порядку и называй их вслух: структуру оценивают.
- Метрики и план оценки идут до архитектуры — большинство кандидатов это пропускает, а ты нет.
- Избегай пяти ловушек: архитектура-вперёд, баззворды, оверинжиниринг, игнор стоимости и отказов, отсутствие мнения.
- Мокай нормально: таймер, вслух, ответ до раскрытия, честные галочки в рубрике, 70%+ покрытия, перепрохождение слабых кейсов.
- Переводи каждый кейс в девяностосекундную историю: ограничение, решение, компромисс, число.
- Первые 90 дней: выкати мелкое, возьми метрику под себя, потом предложи одно изменение с настоящей арифметикой за спиной.

### Копнуть глубже

- [Chip Huyen — AI Engineering book repo](https://github.com/chiphuyen/aie-book)
- [Anthropic — Building effective agents](https://www.anthropic.com/engineering/building-effective-agents)
- [Google SRE Book — Service Level Objectives](https://sre.google/sre-book/service-level-objectives/)
- [Model Context Protocol](https://modelcontextprotocol.io)`,
  };

