      q: String.raw`Твой сервис ходит к одному провайдеру моделей. В плохой день провайдер отдаёт 429 на 4% вызовов. Твой клиент ретраит до 3 раз без джиттера и без бюджета ретраев. Какой продовый исход наиболее вероятен?`,
