      q: String.raw`RAG-эндпойнт отправляет 4 000 входных токенов и получает 400 выходных. Вход стоит $0.30 за миллион токенов, выход — $1.20 за миллион. Какое одно изменение сильнее всего срежет стоимость запроса?`,
