  R.ex["w7d1-e1"] = {
    title: "Цепочка фолбэков: доступность и ожидаемая стоимость",
    brief: "Две формулы, нужные любому ответу про надёжность, — на бумаге, в 20 строк.",
    description: String.raw`Когда ты предлагаешь на собеседовании цепочку фолбэков, ты должен уметь тут же оценить её вслух. Реализуй две формулы с салфетки.

~~~python
def chain_availability(probs):
    ...

def expected_cost(probs, costs):
    ...
~~~

**chain_availability(probs)** — ~probs[i]~ это вероятность того, что звено ~i~ сработало успешно. Запрос падает, только если упали все звенья, значит:

~~~text
availability = 1 - произведение по всем i из (1 - p_i)
~~~

Пустая цепочка возвращает ~0.0~ (запрос обслуживать некому).

**expected_cost(probs, costs)** — звено ~i~ *пробуется* только тогда, когда все предыдущие упали, и ты платишь ~costs[i]~ каждый раз, когда звено ~i~ пробуется (неудачный вызов тоже стоит денег и квоты):

~~~text
E[cost] = сумма по i из  costs[i] * произведение по всем j < i из (1 - p_j)
~~~

Пустая цепочка возвращает ~0.0~. Если ~len(probs) != len(costs)~, брось ~ValueError~.

Разобранный пример:

~~~python
chain_availability([0.99, 0.95])          # 1 - (0.01 * 0.05) = 0.9995
expected_cost([0.99, 0.95], [1.0, 0.2])   # 1.0 + 0.2 * 0.01 = 1.002
~~~

Возвращай обычные float — без округления.

Ракурс собеседования: это и есть арифметика за фразой «добавим фолбэк подешевле, и доступность вырастет». Умение сказать «второе звено стоит мне 0,2 цента, умноженные на 1% проваливающихся вниз запросов» — это то, что превращает баззворд в дизайн.`,
    hints: [
      String.raw`Для доступности веди текущую вероятность того, что всё до сих пор упало, а в конце вычти её из 1.`,
      String.raw`Для стоимости та же текущая вероятность «все предыдущие упали» и есть вес звена i. Начни с 1.0 и умножай на (1 - p_i) после того, как начислил стоимость звена i.`,
      String.raw`Проверяй несовпадение длин первым и бросай ValueError до всякой арифметики, чтобы ошибка не пряталась за IndexError.`,
    ],
  };

