    title: "График бэкоффа, который защитишь у доски",
    brief: "Экспоненциальный, с потолком, детерминированный — джиттер будет позже.",
    description: String.raw`Интервьюеры просят написать график ретраев на доске. Здесь пиши детерминированный скелет; джиттер накладывается сверху в момент вызова (~random.uniform(0, delay)~), и именно поэтому эта функция остаётся тестируемой.

~~~python
def backoff_schedule(base_ms, factor, max_retries, cap_ms):
    ...
~~~

Верни список длины ~max_retries~, где элемент ~i~ (с нуля) равен:

~~~text
delay_i = int(min(cap_ms, base_ms * factor ** i))
~~~

Правила:

- ~int(...)~ обрезает в сторону нуля — дробный множитель вроде 1.5 даёт 337, а не 338.
- ~max_retries == 0~ возвращает ~[]~.
- ~max_retries < 0~, ~base_ms < 0~ или ~cap_ms < 0~ бросают ~ValueError~.

Разобранный пример:

~~~python
backoff_schedule(500, 2, 5, 4000)   # [500, 1000, 2000, 4000, 4000]
backoff_schedule(100, 1.5, 4, 9999) # [100, 150, 225, 337]
~~~

Ракурс собеседования: числа тут важны. График, суммарное ожидание которого превышает терпение пользователя (или таймаут запроса), хуже быстрого отказа — назови потолок и объясни, почему выбрал именно его.`,
