    title: "Цепочка задержек с параллельными группами",
    brief: "Последовательное складывается, параллельное берёт максимум — и критический путь называет себя сам.",
    description: String.raw`Мультимодальные пайплайны — это цепочки шагов, часть которых идёт одновременно. Посчитай сквозную задержку и критический путь.

~~~python
def chain_latency(stages):
    ...
~~~

~stages~ — список словарей: ~{"name": str, "ms": number, "parallel_group": str or None}~. Отсутствующий ключ ~"parallel_group"~ означает ~None~.

Правила:

- Шаги с ~parallel_group~ равным ~None~ идут последовательно: каждый добавляет свои ~ms~.
- Шаги с одинаковым ~parallel_group~ идут одновременно: группа вносит ~max(ms)~ своих членов, засчитанный **один раз**.
- Группа занимает позицию своего **первого** члена во входном порядке.
- При равенстве внутри группы побеждает самый ранний член во входном порядке.

**Верни** ~{"total_ms": ..., "critical_path": [...]}~, где ~total_ms~ округлён до 2 знаков, а ~critical_path~ перечисляет по порядку имя каждого последовательного шага и самого медленного члена каждой группы.

Разобранный пример:

~~~python
stages = [
    {"name": "upload",   "ms": 120, "parallel_group": None},
    {"name": "caption",  "ms": 800, "parallel_group": "enrich"},
    {"name": "embed",    "ms": 300, "parallel_group": "enrich"},
    {"name": "moderate", "ms": 250, "parallel_group": "enrich"},
    {"name": "index",    "ms": 60,  "parallel_group": None},
]
chain_latency(stages)
# {"total_ms": 980.0, "critical_path": ["upload", "caption", "index"]}
~~~

Пустой список возвращает ~{"total_ms": 0.0, "critical_path": []}~.

Ракурс собеседования: когда интервьюер спрашивает «куда уходит задержка?», вот это и есть ответ — а критический путь подсказывает единственный шаг, который стоит оптимизировать.`,
