    title: "Отставание стримингового ASR",
    brief: "Размер чанка плюс real-time factor плюс сеть — и момент, когда он перестаёт успевать.",
    description: String.raw`Стриминговый распознаватель речи буферизует аудио в чанки, расшифровывает каждый и отправляет результат обратно. Оцени худшее отставание между произнесённым словом и приходом его расшифровки.

~~~python
def asr_stream_lag(chunk_ms, rtf, network_ms):
    ...
~~~

~~~text
lag_ms = chunk_ms + chunk_ms * rtf + network_ms
~~~

- ~chunk_ms~ — аудио, буферизуемое до начала расшифровки (полного чанка ты ждёшь всегда).
- ~rtf~ — real-time factor: секунд вычислений на секунду аудио. RTF 0.3 означает 300 мс времени GPU на 1 000 мс аудио.
- ~network_ms~ — время сетевого раунд-трипа.

**Верни** ~{"lag_ms": ..., "realtime": ...}~, где ~lag_ms~ округлён до 2 знаков, а ~realtime~ равен ~True~ только когда ~rtf < 1.0~ (строго): при RTF 1.0 и выше расшифровка медленнее, чем приходит аудио, очередь растёт неограниченно, и посчитанное отставание относится только к *первому* чанку.

Брось ~ValueError~, если ~chunk_ms <= 0~, ~rtf < 0~ или ~network_ms < 0~.

Разобранный пример:

~~~python
asr_stream_lag(320, 0.35, 80)   # {"lag_ms": 512.0, "realtime": True}
asr_stream_lag(500, 1.2, 60)    # {"lag_ms": 1160.0, "realtime": False}
~~~

Ракурс собеседования: это объясняет, почему размер чанка — это UX-ручка. Чанки поменьше режут отставание, но бьют по точности (меньше контекста на чанк) и умножают накладные расходы на запросы.`,
