  R.ex["w7d5-e1"] = {
    title: "nDCG at k",
    brief: "Метрика ранжирования, которую интервьюеры просят написать на доске.",
    description: String.raw`Реализуй normalized discounted cumulative gain — стандартную метрику ранжирования с градуированной релевантностью.

~~~python
def ndcg_at_k(relevances, k):
    ...
~~~

~relevances~ — градуированная релевантность каждого результата **в том порядке, в каком их отранжировала твоя система** (больше — лучше, 0 значит нерелевантно). ~k~ — отсечка.

~~~text
DCG@k  = сумма по позициям i = 1..k из  rel_i / log2(i + 1)
IDCG@k = та же формула по релевантностям, отсортированным по убыванию
nDCG@k = DCG@k / IDCG@k
~~~

Правила:

- Позиции считаются с единицы, поэтому первый результат делится на ~log2(2) = 1~, а второй — на ~log2(3)~.
- Если ~k~ больше числа результатов, используй их все.
- Верни ~0.0~, когда список пуст, когда ~k <= 0~ или когда IDCG равен 0 (все релевантности нулевые).
- Возвращай обычный float, без округления.

Разобранный пример:

~~~python
ndcg_at_k([3, 2, 3, 0, 1, 2], 6)   # about 0.9608
ndcg_at_k([3, 0], 2)               # 1.0  (already the ideal order)
ndcg_at_k([0, 3], 2)               # about 0.6309
~~~

Ракурс собеседования: nDCG — это то, чем ты сравниваешь ранкеры офлайн. Будь готов сказать, зачем нужна логарифмическая скидка (позиции ниже сгиба видят реже) и зачем нужна нормировка (иначе запросы с бо́льшим числом релевантных результатов доминировали бы в среднем).`,
    hints: [
      String.raw`Напиши маленький хелпер dcg(rels) и вызови его дважды: один раз с данным порядком, один раз с sorted(rels, reverse=True).`,
      String.raw`Используй enumerate с нуля и дели на math.log2(i + 2) — это и есть скидка log2(ранг + 1) при рангах с единицы.`,
      String.raw`Режь до k внутри хелпера и защитись от нулевого идеального DCG до деления.`,
    ],
  };

