        explain: String.raw`В стриминговом интерфейсе пользователь начинает читать сразу, поэтому воспринимаемую скорость определяет время до первого токена; общее время значит куда меньше, когда текст уже льётся. Средние ещё и полностью прячут хвост, а именно там живёт плохой опыт — всегда называй перцентили.`,
